    // -- ByteMapWireTests --
    //
    // A `format: byte` map value is native bytes in memory and a base64 string
    // on the wire, exactly like a byte scalar or array. A plain assignment
    // would hand jsonEncode a Uint8List, which it writes as an int array.
    test('serialize writes format:byte map values as base64 strings', () {
      final vault = BinaryVault(
        labels: <String, Uint8List>{
          'a': Uint8List.fromList(<int>[1, 2, 3]),
          'b': Uint8List.fromList(<int>[255]),
        },
      );

      final wire = jsonDecode(serialize(vault)) as Map<String, dynamic>;

      expect(
        wire['labels'],
        equals(<String, dynamic>{'a': 'AQID', 'b': '/w=='}),
      );
    });

    test(
      'bhv serializationobject 026 format:byte map values round-trip through the wire form',
      () {
        final vault = BinaryVault(
          seal: Uint8List.fromList(<int>[9, 8]),
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[1, 2, 3]),
          },
        );

        final restored = BinaryVault.fromJson(
          jsonDecode(serialize(vault)) as Map<String, dynamic>,
        );

        expect(restored, equals(vault));
        expect(
          restored.labels!['a'],
          equals(Uint8List.fromList(<int>[1, 2, 3])),
        );
      },
    );

    // -- BinaryVaultEqualityTests --
    //
    // Equality compares every byte array by content: a bare array, each element
    // of a list and each value of a map. Equal content in distinct arrays is
    // equal and hashes alike.
    test(
      'bhv serializationobject 075 equality compares byte arrays by content (bare, list and map)',
      () {
        final base = BinaryVault(
          seal: Uint8List.fromList(<int>[1, 2]),
          shards: <Uint8List>[
            Uint8List.fromList(<int>[3]),
          ],
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[4]),
          },
        );
        expect(
          base,
          isNot(
            equals(
              BinaryVault(
                seal: Uint8List.fromList(<int>[1, 9]),
                shards: <Uint8List>[
                  Uint8List.fromList(<int>[3]),
                ],
                labels: <String, Uint8List>{
                  'a': Uint8List.fromList(<int>[4]),
                },
              ),
            ),
          ),
        );
        expect(
          base,
          isNot(
            equals(
              BinaryVault(
                seal: Uint8List.fromList(<int>[1, 2]),
                shards: <Uint8List>[
                  Uint8List.fromList(<int>[9]),
                ],
                labels: <String, Uint8List>{
                  'a': Uint8List.fromList(<int>[4]),
                },
              ),
            ),
          ),
        );
        expect(
          base,
          isNot(
            equals(
              BinaryVault(
                seal: Uint8List.fromList(<int>[1, 2]),
                shards: <Uint8List>[
                  Uint8List.fromList(<int>[3]),
                ],
                labels: <String, Uint8List>{
                  'a': Uint8List.fromList(<int>[9]),
                },
              ),
            ),
          ),
        );
      },
    );

    test(
      'bhv serializationobject 206 a differing map key makes two models unequal',
      () {
        final left = BinaryVault(
          labels: <String, Uint8List>{
            'first': Uint8List.fromList(<int>[7, 8]),
          },
        );
        final right = BinaryVault(
          labels: <String, Uint8List>{
            'second': Uint8List.fromList(<int>[7, 8]),
          },
        );
        expect(left, isNot(equals(right)));
      },
    );

    test(
      'bhv serializationobject 005 a differing byte inside a map value makes them unequal',
      () {
        final a = BinaryVault(
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[1, 2]),
          },
        );
        final b = BinaryVault(
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[1, 3]),
          },
        );
        expect(a, isNot(equals(b)));
      },
    );

    test(
      'bhv serializationobject 009 a list of byte arrays is not equal to a map of them',
      () {
        final asList = BinaryVault(
          shards: <Uint8List>[
            Uint8List.fromList(<int>[1]),
          ],
        );
        final asMap = BinaryVault(
          labels: <String, Uint8List>{
            '0': Uint8List.fromList(<int>[1]),
          },
        );
        expect(asList, isNot(equals(asMap)));
      },
    );

    test(
      'bhv serializationobject 090 instances holding equal content are equal though every array is distinct',
      () {
        final a = BinaryVault(
          seal: Uint8List.fromList(<int>[1, 2]),
          shards: <Uint8List>[
            Uint8List.fromList(<int>[3]),
          ],
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[4]),
          },
        );
        final b = BinaryVault(
          seal: Uint8List.fromList(<int>[1, 2]),
          shards: <Uint8List>[
            Uint8List.fromList(<int>[3]),
          ],
          labels: <String, Uint8List>{
            'a': Uint8List.fromList(<int>[4]),
          },
        );
        expect(identical(a.seal, b.seal), isFalse);
        expect(a, equals(b));
        expect(a.hashCode, equals(b.hashCode));
      },
    );

    // -- DiscardExtrasOnDeserializeTests --
    //
    // fromJson must read only declared properties and silently drop unknown
    // keys (no exception thrown). This protects clients against new server
    // fields added after the SDK was generated.
    test(
      'bhv serialization 068 building a model in code does not validate it, keeping the values as given',
      () {
        final pet = Pet(
          name: '',
          photoUrls: <String>{},
          nickname: 'ZZZZZZZZZZ',
        );

        expect(pet.name, equals(''));
        expect(pet.nickname, equals('ZZZZZZZZZZ'));
      },
    );

    test(
      'bhv serialization 069 schema constraints such as pattern and length are not enforced, so out-of-bound values are accepted',
      () {
        final pet = deserialize<Pet>(
          '{"name":"x","photoUrls":[],"nickname":"ZZZZZZZZZZ"}',
          Pet.fromJson,
        );

        expect(pet!.nickname, equals('ZZZZZZZZZZ'));
      },
    );

    test(
      'bhv serialization 070 a JSON null is accepted where a field is optional and decodes to null',
      () {
        final pet = deserialize<Pet>(
          '{"name":"x","photoUrls":[],"nickname":null}',
          Pet.fromJson,
        );

        expect(pet!.nickname, isNull);
      },
    );

    test(
      'bhv serialization 072 keys the model does not declare are skipped without error, scalar or nested',
      () {
        final pet = Pet.fromJson(<String, dynamic>{
          'id': 1,
          'name': 'Fido',
          'photoUrls': <String>['http://x/y.jpg'],
          'unknownField': 'value',
          'nestedExtra': {'foo': 'bar'},
        });

        expect(pet.name, equals('Fido'));
      },
    );

    test(
      'bhv serialization 073 a required field that is missing fails decoding with an error naming that field',
      () {
        expect(
          () => deserialize<Pet>('{"photoUrls":[]}', Pet.fromJson),
          throwsA(predicate((e) => e.toString().contains('name'))),
        );
      },
    );

    test(
      'bhv serializationobject 082 fromJson silently ignores unknown extra fields',
      () {
        final input = <String, dynamic>{
          'id': 1,
          'name': 'Fido',
          'photoUrls': <String>['http://x/y.jpg'],
          // Unknown / future fields:
          'unknownField': 'value',
          'serverSideOnly': 12345,
          'nestedExtra': {'foo': 'bar'},
        };
        final pet = Pet.fromJson(input);
        expect(pet.id, equals(1));
        expect(pet.name, equals('Fido'));
        // Declared optional fields stay null when absent.
        expect(pet.category, isNull);
        expect(pet.status, isNull);
      },
    );

    // -- RequiredFieldHardFailTests (DIVERGENCE #10) --
    //
    // Deserialising a model whose required, non-nullable field is MISSING or
    // explicitly NULL must hard-fail with the SDK's SerializationException rather
    // than silently building a partial object. Pet requires both `name` and
