    );

    test(
      'bhv models 017 a copy can set or clear an optional field and the original model keeps its value',
      () {
        const original = Category(id: 1, name: 'dog');
        final cleared = original.copyWith(name: null);

        expect(cleared.name, isNull);
        expect(original.name, equals('dog'));
      },
    );

    test(
      'bhv models 019 two models with a different value in any field compare unequal',
      () {
        expect(
          const Category(id: 1, name: 'a'),
          isNot(equals(const Category(id: 1, name: 'b'))),
        );
        expect(
          const Category(id: 1, name: 'a'),
          isNot(equals(const Category(id: 2, name: 'a'))),
        );
      },
    );

    test(
      'bhv models 020 models with the same field values compare equal and hash alike',
      () {
        const first = Category(id: 1, name: 'a');
        final second = Category(id: 1, name: 'a');

        expect(first, equals(second));
        expect(first.hashCode, equals(second.hashCode));
        expect(<Category>{first, second}, hasLength(1));
      },
    );

    test(
      'bhv models 021 each member of an integer-backed enum carries its declared number as its value',
      () {
        expect(Priority.number1.value, equals(1));
        expect(Priority.number2.value, equals(2));
        expect(Priority.number3.value, equals(3));
      },
    );

    test(
      'bhv models 024 a newly built model leaves its optional properties unset',
      () {
        const empty = Category();

        expect(empty.id, isNull);
        expect(empty.name, isNull);
      },
    );

    test(
      'bhv serialization 020 a field the caller leaves unset is written with its schema default value',
      () {
        expect(
          jsonDecode(serialize(const Defaults())),
          containsPair('retries', 3),
        );
        expect(
          jsonDecode(serialize(const Defaults())),
          containsPair('mode', 'medium'),
        );
      },
    );

    test(
      'bhv models 013 a newly built model starts with an empty additional properties collection, never null',
      () {
        final model = Metadata.fromJson(<String, dynamic>{});

        expect(model.additionalProperties, isNotNull);
        expect(model.additionalProperties, isEmpty);
      },
    );

    test(
      'bhv models 015 a changed copy of a model keeps the additional properties of the original',
      () {
        final original = Metadata.fromJson(<String, dynamic>{'extra': 'a'});
        final changed = original.copyWith(createdAt: null);

        expect(changed.additionalProperties, equals({'extra': 'a'}));
      },
    );

    test(
      'bhv models 018 models whose decimal fields hold numerically equal values compare equal',
      () {
        const first = Defaults(ratio: 1.0);
        const second = Defaults(ratio: 1.00);

        expect(first, equals(second));
      },
    );

    test(
      'bhv models 022 a generated model whose schema allows undeclared properties reports that it does',
      () {
        final model = Metadata.fromJson(<String, dynamic>{'extra': 'x'});

        expect(model.additionalProperties.containsKey('extra'), isTrue);
      },
    );

    test(
      'bhv models 023 undeclared keys named like the SDK method names are kept as additional properties',
      () {
        final model = Metadata.fromJson(<String, dynamic>{
          'toJson': 'a',
          'copyWith': 'b',
        });

        expect(
          model.additionalProperties,
          equals({'toJson': 'a', 'copyWith': 'b'}),
        );
        expect(model.toJson()['toJson'], equals('a'));
      },
    );

    test(
      'bhv serialization 012 keys of maps are written in ascending order so equal data always produces identical output',
      () {
        expect(serialize({'b': 1, 'a': 2}), equals('{"a":2,"b":1}'));
      },
    );

    test(
      'bhv serialization 019 an unset optional property is left out of the serialized output',
      () {
        expect(
          serialize(const Category(name: 'dog')),
          equals('{"name":"dog"}'),
        );
      },
    );

    test(
      'bhv serialization 021 values with equal content compare equal and hash alike, and differing content does not',
      () {
        const first = Category(id: 1, name: 'a');
        const second = Category(id: 1, name: 'a');
        const third = Category(id: 1, name: 'b');

        expect(first, equals(second));
        expect(first.hashCode, equals(second.hashCode));
        expect(first, isNot(equals(third)));
      },
    );

    test(
      'bhv serialization 040 a form value writes each date-time, number, integer and boolean in its canonical wire text',
      () {
        expect(toFormValue(true), equals('true'));
        expect(toFormValue(3), equals('3'));
        expect(toFormValue(2.5), equals('2.5'));
        expect(
          toFormValue(DateTime.utc(2024, 1, 1)),
          startsWith('2024-01-01T00:00:00'),
        );
      },
    );

    test(
      'bhv serialization 041 a time string in hours, minutes and seconds form is accepted',
      () {
        expect(() => validatePartialTime('10:20:30'), returnsNormally);
      },
    );

    test(
      'bhv serialization 043 a time of day is written as hours, minutes and seconds and never as a full date-time',
      () {
        expect(validatePartialTime('10:20:30'), isNot(contains('T')));
      },
    );

    test(
      'bhv serialization 046 a duration fraction is written in the shortest group of three, six or nine digits',
      () {
        expect(
          formatProtobufDuration(const Duration(milliseconds: 1500)),
          equals('1.500s'),
        );
        expect(
          formatProtobufDuration(const Duration(microseconds: 1500100)),
          equals('1.500100s'),
        );
      },
    );

    test(
      'bhv serialization 047 a very large duration is formatted without overflow and an out-of-range duration string is refused',
      () {
        expect(
          () => formatProtobufDuration(const Duration(days: 365 * 200)),
          returnsNormally,
        );
        expect(
          () => parseProtobufDuration('999999999999999999999s'),
          throwsA(isA<SerializationException>()),
        );
      },
    );

    test(
      'bhv serialization 048 a duration written on its own is written as its protobuf seconds string',
      () {
        expect(
          formatProtobufDuration(const Duration(seconds: 2)),
          equals('2s'),
        );
      },
    );

    test(
      'bhv serialization 052 undeclared keys are kept as additional properties on a model read from the wire',
      () {
        final model = Metadata.fromJson(<String, dynamic>{
          'undeclared': 'kept',
        });

        expect(model.additionalProperties, containsPair('undeclared', 'kept'));
        expect(model.toJson(), containsPair('undeclared', 'kept'));
      },
    );

    test(
      'bhv serialization 053 undeclared keys held by a model are written back as keys of that model',
      () {
        final json = Metadata.fromJson(<String, dynamic>{
          'undeclared': 'kept',
        }).toJson();

        expect(json['undeclared'], equals('kept'));
      },
    );

    test(
      'bhv serialization 001 the text form of an enum member is exactly its declared wire value',
      () {
        expect(Swatch.green.value, equals('green'));
      },
    );

    test(
      'bhv serialization 002 an enum member held by a model is written as its exact declared wire string',
      () {
        expect(
          serialize(Defaults(swatch: Swatch.green)),
          contains('"swatch":"green"'),
        );
      },
    );

    test(
      'bhv serialization 003 a wire value an enum declares decodes to the member carrying exactly that value',
      () {
        expect(
          Defaults.fromJson({'swatch': 'green'}).swatch,
          equals(Swatch.green),
        );
      },
    );

    test(
      'bhv serialization 004 a generated enum refuses any value outside its declared members',
      () {
        expect(
          () => Defaults.fromJson({'swatch': 'purple'}),
          throwsA(isA<ArgumentError>()),
        );
      },
    );

    group('native value formats', () {
      NativeValues decode(String json) =>
          deserialize<NativeValues>(json, NativeValues.fromJson)!;

      test(
        'bhv serializationobject 403 a duration field is the native Duration',
        () {
          final Duration? wait = decode('{"wait":"3600s"}').wait;

          expect(wait, equals(const Duration(hours: 1)));
        },
      );

      test(
        'bhv serializationobject 404 a duration keeps every microsecond and truncates the rest toward zero',
        () {
          expect(
            decode('{"wait":"1.123456789s"}').wait,
            equals(const Duration(seconds: 1, microseconds: 123456)),
          );
          expect(
            decode('{"wait":"-1.123456789s"}').wait,
            equals(-const Duration(seconds: 1, microseconds: 123456)),
          );
        },
      );

      test(
        'bhv serializationobject 405 an ipv4 field is the address text and is kept unchanged',
        () {
          expect(
            serialize(decode('{"address4":"192.0.2.1"}')),
            equals('{"address4":"192.0.2.1"}'),
          );
        },
      );

      test(
        'bhv serializationobject 406 an ipv6 field keeps the address text unchanged',
        () {
          for (final text in ['2001:0DB8:0:0:0:0:0:1', '2001:db8::1', '::1']) {
            expect(
              serialize(decode('{"address6":"$text"}')),
              equals('{"address6":"$text"}'),
            );
          }
        },
      );

      test(
        'bhv serializationobject 408 every absolute URI of the corpus round-trips byte for byte',
        () {
          for (final text in [
            'https://example.com',
            'HTTP://EXAMPLE.com:80/a%2fb?x=1&x=2#frag',
            'mailto:a@b.c',
            'urn:isbn:0451450523',
            "https://example.com/[x]?q='a'",
            'https://example.com?',
            'https://example.com/%7euser',
            'https://[2001:db8::1]:8443/',
          ]) {
            final json = jsonEncode({'homepage': text});

            expect(serialize(decode(json)), equals(json), reason: text);
          }
        },
      );

      test(
        'bhv serializationobject 409 a hostname and an email are kept as given',
        () {
          const json = '{"host":"not a host!","contact":"x@"}';

          expect(serialize(decode(json)), equals(json));
        },
      );

      test(
        'bhv serializationparam 104 a duration parameter is written in the protobuf form',
        () {
          expect(stringify(const Duration(hours: 1)), equals('3600s'));
        },
      );

      test(
        'bhv serializationparam 105 an address parameter is its text unchanged',
        () {
          expect(stringify('2001:db8::1'), equals('2001:db8::1'));
        },
      );
    });
  });

  group('enum member names and descriptions', () {
    String source(String name) =>
        File('lib/src/models/$name.dart').readAsStringSync();

    test(
      'bhv enums 001 a string member named by an array exposes the given name and its wire value',
      () {
        expect([
          Tier.small.value,
          Tier.medium.value,
          Tier.large.value,
        ], equals(['s', 'm', 'l']));
        final item = deserialize<Subscription>(
          '{"rank":1,"tier":"m"}',
          Subscription.fromJson,
        );
        expect(item!.tier, equals(Tier.medium));
      },
    );

    test(
      'bhv enums 002 an integer member named by an array exposes the given name and its number',
      () {
        expect([
          Rank.low.value,
          Rank.medium.value,
          Rank.high.value,
        ], equals([1, 2, 3]));
        final item = deserialize<Subscription>(
          '{"rank":3}',
          Subscription.fromJson,
        );
        expect(item!.rank, equals(Rank.high));
        expect(serialize(item), contains('"rank":3'));
      },
    );

    test(
      'bhv enums 003 an object keyed by wire value names the members it lists',
      () {
        expect(
          deserialize<Subscription>(
            '{"rank":1,"stage":"paused"}',
            Subscription.fromJson,
          )!.stage,
          equals(Stage.onHold),
        );
        expect(
          deserialize<Subscription>(
            '{"rank":1,"stage":"active"}',
            Subscription.fromJson,
          )!.stage,
          equals(Stage.active),
        );
      },
    );

    test(
      'bhv enums 004 a supplied name that is not a legal identifier is cleaned and cased',
      () {
        expect(Stage.onHold.value, equals('paused'));
      },
    );

    test(
      'bhv enums 005 two supplied names that collide after casing keep distinct names and wires',
      () {
        expect(Stage.active.value, equals('active'));
        expect(Stage.active2.value, equals('live'));
        expect(
          deserialize<Subscription>(
            '{"rank":1,"stage":"live"}',
            Subscription.fromJson,
          )!.stage,
          equals(Stage.active2),
        );
      },
    );

    test(
      'bhv enums 006 an inline property enum takes its member names from its own keys',
      () {
        expect(SubscriptionIntervalEnum.monthly.value, equals('month'));
        expect(SubscriptionIntervalEnum.yearly.value, equals('year'));
      },
    );

    test(
      'bhv enums 007 a default on a referenced enum property starts at the supplied member',
      () {
        expect(const Subscription(rank: Rank.low).tier, equals(Tier.medium));
        expect(
          deserialize<Subscription>('{"rank":1}', Subscription.fromJson)!.tier,
          equals(Tier.medium),
        );
      },
    );

    test(
      'bhv enums 008 encoding writes the wire value and decoding rejects a supplied name',
      () {
        expect(
          const Subscription(
            rank: Rank.low,
            tier: Tier.medium,
          ).toJson()['tier'],
          equals('m'),
        );
        expect(
          () => deserialize<Subscription>(
            '{"rank":1,"tier":"Medium"}',
            Subscription.fromJson,
          ),
          throwsA(
            predicate(
              (e) =>
                  e is SerializationException &&
                  e.toString().contains('Medium'),
            ),
          ),
        );
      },
    );

    test(
      'bhv enums 009 a description is the one-line comment directly above the member',
      () {
        expect(source('tier'), contains('  /// The smallest tier.\n  small('));
        expect(source('tier'), contains('  /// The medium tier.\n  medium('));
      },
    );

    test(
      'bhv enums 010 a member without a description keeps the comment it has today',
      () {
        expect(
          source('rank'),
          contains('  /// Represents the value 2.\n  medium(2),'),
        );
      },
    );

    test(
      'bhv enums 011 a description with terminators and sigils still yields a comment',
      () {
        expect(
          source('tier'),
          contains(
            r'  /// The largest tier. Ends with */ and #{x} and $x.'
            '\n  large(',
          ),
        );
      },
    );
  });
}
